import{_ as n,l as i,o as e,c as l,v as r,p as o,x as t,d as s,i as B,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"仓单与交割","description":"","frontmatter":{"title":"仓单与交割","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/futures-delivery.md","filePath":"quant/futures-delivery.md","lastUpdated":1789023840000}'),d={name:"quant/futures-delivery.md"};function A(u,a,h,c,m,f){const E=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="仓单与交割" tabindex="-1">仓单与交割 <a class="header-anchor" href="#仓单与交割" aria-label="Permalink to &quot;仓单与交割&quot;">​</a></h1><div class="epigraph"><p>期货把现货的品质、地点与时间选择权写进交割程序；仓单是这些选择权的凭证，不是仓库里吨数的同义词。</p><footer>—— Hull 对交割与基差的制度描述；选择权见 Gay &amp; Manaster；仓储见 Working</footer></div><p><a href="/quant/calendar-spread-arb">上一课</a>交易同一商品不同到期的价差，经济对象是仓储与便利收益的时间差分，不是无条件均值回归；交割选择权与挤仓会改写这条价差。缺口是收敛锚：没有仓单与交割规则，<a href="/quant/cash-and-carry">期现套利</a> 没有句点，曲线也失去可检验的现货。本课钉仓单：期货对齐最便宜可交割凭证，不是全国库存或现货指数。不重讲 Working 持有费的跨期表述。后课保证金默认交割月仓位已经带地点、品质与时间期权。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>跨期价差对齐的是仓储的时间差分；没有可交割仓单，这条差分没有现货锚。仓单代表特定地点、特定品质、特定仓库的存货，通常还附带生成、注销、转让的程序与费用。期货价格对齐的是「最便宜可交割的那张仓单」，不是全国产量或某个现货指数。问题因而永远是：有多少库存是注册的、在哪个地点、升贴水表如何把不同仓单折成合约标准品。可交割库存远小于总库存时，曲线可以在宏观供给宽松时仍出现近月挤兑。反向地，注册仓单很多但都在错误的港口，对需要另一港口现货的贸易商等于没有库存。</p><p>交割还有时间期权：空头选择在交割期内的哪一天交、有时还有意向通知与匹配规则。国债期货的时间期权与万能牌期权有 Kane–Marcus、Hemler 的定价文献；商品上同等重要，只是名字叫通知日、仓单配对与滞期。忽略时间，把交割月当成一个点，会低估空头的期权、高估多头接货的确定性。现金结算合约把问题换成结算价窗口是否可操纵、是否与可交易现货同步，那是另一套基差，不能用仓单逻辑去套。</p><h3 id="注册、注销与「纸库存」" tabindex="-1">注册、注销与「纸库存」 <a class="header-anchor" href="#注册、注销与「纸库存」" aria-label="Permalink to &quot;注册、注销与「纸库存」&quot;">​</a></h3><p>仓单可以生成（现货入库检验后注册）也可以注销（提出仓库、转为普通现货）。注销使可交割供给突然下降，近月可以跳涨，而总库存报告尚未变化。这是<a href="/quant/inventory-curve">库存报告与曲线</a>必须把「总库存」与「可交割库存」分列的原因。纸货市场（远期船货、场外仓单转让）与期货仓单之间有基差；贸易商在两条市场之间套利，受检验、运输与信用约束。把 LME 仓单、CME 交割地点、上期所指定交割仓库当成同一个存量，地点期权会被写丢。</p><p><span class="marginnote">交易所公布的仓单周报是滞后且分类粗的。真正能交的是你名下或可买到的特定仓单。用周报总量去做交割月空头，等于用全国住房存量去交割某一小区的期货。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>交割流程应写成状态机：持仓进入交割月 → 意向通知 → 匹配 → 仓单过户 → 货款与升贴水 → 出库或继续持有仓单。每一步有截止时间与失败罚则。期现与跨期的风险系统必须在进入交割月前把期货仓位标成「或有实物」，保证金、限额与是否允许继续持有空头，都要切换规则。EFP、EFS 与场外基差合同是把期货换成现货的平行通道，往往比官方交割更常用；它们的价格应进入公平价值，而不是把官方交割当成唯一收敛。</p><p>品质与地点升贴水表是定价输入。空头会交最便宜的合格品，这就是商品 CTD。计算每一种可交割仓单的净发票金额，取最小者，得到期货应对齐的现货。升贴水若长期不更新，期货会系统性地偏离开真实贸易现货，套利资本会把货物运向被高估的交割地——直到仓库或规则调整。容量是可生成仓单的速度与可注销的速度，不是期货名义。</p><h3 id="交割选择权如何进入期货价格" tabindex="-1">交割选择权如何进入期货价格 <a class="header-anchor" href="#交割选择权如何进入期货价格" aria-label="Permalink to &quot;交割选择权如何进入期货价格&quot;">​</a></h3><p>Gay–Manaster 的品质期权降低空头愿意接受的期货价格（相对标准品现货），因为空头持有一篮子交割权。地点与时间期权同理。存货低、合格品牌少时，期权价值下降，期货更贴近特定现货；存货高、清单长时，期权价值上升，期货可以持续低于你盯着的那一种现货。这不是错误定价，是选择权。国债上的对应物是转换因子与 CTD 切换，见<a href="/quant/ctd-cheapest">最便宜可交割</a>。商品没有转换因子表时，升贴水表扮演近似角色，但通常更粗、调整更慢。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>收敛机制：若期货明显高于最便宜可交割仓单加交割摩擦，买仓单空期货并进入交割；反向则在可借仓单时反向操作。摩擦包括过户费、检验、出库排队与资金占用。Working 的仓储在交割地被局部化：全国库存高而交割地库存低，局部持有费可以与宏观叙事相反。挤仓机制：控制可交割仓单的一方迫使空头在期货上平仓，近月脱离仓单 parity。Pirrong 分析角落与挤压时强调可交割供给的弹性；弹性低，操纵或挤兑的空间大。监管与持仓限额、交割月加严的保证金，是对这一机制的制度回应，也会改变合法套利的容量。</p><p>仓单与融资相连。仓单可质押，贸易商用仓单融资做期现；融资冻结时，本可交割的库存无法被套利资本调动，基差张开。这与<a href="/quant/futures-margin">保证金与盯市</a>的资金螺旋是同一类约束，只是抵押品从现金变成了铜和大豆。</p><h3 id="破裂-检验失败、堵港、规则修改" tabindex="-1">破裂：检验失败、堵港、规则修改 <a class="header-anchor" href="#破裂-检验失败、堵港、规则修改" aria-label="Permalink to &quot;破裂：检验失败、堵港、规则修改&quot;">​</a></h3><p>检验不合格使仓单作废或降级，升贴水突变。港口拥堵使出库权利无法在需要时行使，多头接货后持有的是被困存货。交易所修改交割地点、品牌清单或升贴水，CTD 切换，旧的期现账立即重估。现金替代或强制结算在极端行情出现时，实物收敛被行政替换，基差停在当时的窗口价。这些不是尾部花絮，而是交割策略的一等情景。</p><p><span class="marginnote">多头在交割月接货若没有下游、没有库容、没有资金，接货就是亏损。期货多头的「权利」包含了承担实物操作的义务。把交割月多头当成现金指数的跟踪，会在第一次匹配到仓单时发现跟踪误差以吨计。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用现货指数替换仓单 parity。不要假设所有公布库存都可交割。不要在交割月沿用非交割月的日历价差模型。成本含仓单过户、检验、出库、滞期、以及接货后的再销售折价。容量受指定仓库库容与注册速度限制；未平仓量大于可交割库存时，多余的仓位必须在期货上平掉，价格发现会离开现货、留在挤仓。</p><p>与股指期货现金结算相比，商品交割把微观结构从订单簿延伸到码头。风险报告应列出：注册仓单、可生成潜力、CTD 地点、升贴水、以及本账户是否具备接货资质。没有接货资质的账户不应把交割月持仓当成套利，只应当成必须在进入交割前退出的金融合约。Hull 的教材章节足够建立语言；具体市场必须读该交易所的交割手册，而不是用另一个交易所的仓单故事外推。</p><p><span class="marginnote">EFP 成交价可以长期偏离官方交割 parity，因为场外信用、增值税与运输被写进 EFP。把 EFP 当「免费期现」而不检查对手方与货物，是把信用风险叫做套利。</span></p>',24)),(e(),o(p,null,{default:t(()=>[B(E,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E6%80%BB%E5%BA%93%E5%AD%98%22%5D%20--%3E%20REG%5B%22%E6%B3%A8%E5%86%8C%E4%BB%93%E5%8D%95%20%2F%20%E5%8F%AF%E4%BA%A4%E5%89%B2%E5%BA%93%E5%AD%98%22%5D%0A%20%20REG%20--%3E%20CTD%5B%22%E6%9C%80%E4%BE%BF%E5%AE%9C%E5%8F%AF%E4%BA%A4%E5%89%B2%E5%9C%B0%E7%82%B9%E4%B8%8E%E5%93%81%E8%B4%A8%22%5D%0A%20%20PREM%5B%22%E5%8D%87%E8%B4%B4%E6%B0%B4%E4%B8%8E%E8%BF%87%E6%88%B7%E8%B4%B9%22%5D%20--%3E%20CTD%0A%20%20CTD%20--%3E%20PAR%5B%22%E4%BB%93%E5%8D%95%20parity%22%5D%0A%20%20FUT%5B%22%E6%9C%9F%E8%B4%A7%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20GAP%5B%22%E7%9B%B8%E5%AF%B9%20parity%20%E7%9A%84%E5%9F%BA%E5%B7%AE%22%5D%0A%20%20PAR%20--%3E%20GAP%0A%20%20GAP%20--%3E%7C%22%E8%B6%85%E8%BF%87%E6%91%A9%E6%93%A6%E4%B8%94%E5%8F%AF%E8%BF%87%E6%88%B7%22%7C%20DLV%5B%22%E4%BA%A4%E5%89%B2%E6%88%96%20EFP%22%5D%0A%20%20REG%20--%3E%7C%22%E6%B3%A8%E9%94%80%20%2F%20%E5%B1%80%E9%83%A8%E7%9F%AD%E7%BC%BA%22%7C%20SQ%5B%22%E8%BF%91%E6%9C%88%E6%8C%A4%E4%BB%93%22%5D%0A%20%20DLV%20--%3E%20PHYS%5B%22%E5%87%BA%E5%BA%93%E3%80%81%E5%86%8D%E9%94%80%E5%94%AE%E6%88%96%E7%BB%A7%E7%BB%AD%E4%BB%93%E5%82%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>仓单是指定地点与品质的可交割凭证；期货对齐的是最便宜可交割仓单，不是现货指数或全国库存。</li><li>空头持有品质、地点与时间选择权（Gay–Manaster）；升贴水表与交割程序决定期权价值。</li><li>Working 的仓储必须局部化到交割地；可交割供给弹性低时出现挤仓（Pirrong 一类分析）。</li><li>生成/注销、检验、堵港与规则修改是破裂模式；无接货能力则交割月仓位不是套利。</li><li>出处：Hull, <em>Options, Futures, and Other Derivatives</em>；Working, <em>AER</em>, 1949；Gay and Manaster, <em>JFE</em>, 1984；Pirrong 对挤压与可交割供给的分析；Kane and Marcus, <em>Journal of Finance</em>, 1986（时间/万能牌期权的利率期货对照）；交易所交割手册为制度细节的第一来源。</li></ul>',2))])}const P=n(d,[["render",A]]);export{_ as __pageData,P as default};
